using System; using System.Web.UI; using RecepcionDocumental.Data;
namespace RecepcionDocumental { public partial class Gmail_Mensaje_Ver : Page { protected void Page_Load(object sender, EventArgs e) { if (IsPostBack) return; long id; if (!long.TryParse(Request.QueryString["id"], out id) || id <= 0) { litAviso.Text = "Indicá un identificador de mensaje válido."; return; } GmailMensajeInfo mensaje; if (!GmailRepository.TryGetMensaje(id, out mensaje)) { litAviso.Text = "No se pudo consultar la estructura inicial de la base de datos."; return; } if (mensaje == null) { litAviso.Text = "No se encontró el mensaje solicitado."; return; } pnlAviso.Visible = false; pnlMensaje.Visible = true; litAsunto.Text = Server.HtmlEncode(mensaje.Asunto); litRemitente.Text = Server.HtmlEncode(mensaje.Remitente); litCuenta.Text = Server.HtmlEncode(mensaje.CuentaEmail); litFecha.Text = mensaje.FechaMensajeUtc.ToString("dd/MM/yyyy HH:mm"); litGmailId.Text = Server.HtmlEncode(mensaje.GmailMessageId); litSnippet.Text = Server.HtmlEncode(mensaje.Snippet ?? "Sin resumen disponible"); } } }
